import{_ as e,o as c,c as r,ag as d}from"./chunks/framework.BaNuf0sO.js";const p=JSON.parse('{"title":"form 表单族","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/form/README.md","filePath":"docs/core/src/components/form/README.md"}'),t={name:"docs/core/src/components/form/README.md"};function a(s,o,i,m,n,l){return c(),r("div",null,[...o[0]||(o[0]=[d('<h1 id="form-表单族" tabindex="-1">form 表单族 <a class="header-anchor" href="#form-表单族" aria-label="Permalink to &quot;form 表单族&quot;">​</a></h1><p>配置式表单核心（13 组件，最大族）：<code>list</code> 配置驱动渲染 / 校验 / 序列化，<code>data</code> 同引用绑定，generate / parse / stringify 三方法 round-trip。</p><h2 id="组件文档-docs" tabindex="-1">组件文档（docs/） <a class="header-anchor" href="#组件文档-docs" aria-label="Permalink to &quot;组件文档（docs/）&quot;">​</a></h2><ul><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormMain.html">FormMain</a> — 配置式表单核心容器</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormSearch.html">FormSearch</a> — 搜索表单（折叠 / 操作区 / staticQuery）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormSubmitPanel.html">FormSubmitPanel</a> — 纯表单空间一等公民（提交 / 取消 / 重置操作区）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormSubmitBtn.html">FormSubmitBtn</a> — 提交按钮（validate → stringify → submitFn 管线）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormItemNestForm.html">FormItemNestForm</a> — 嵌套子表单（C1，级联校验）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormItemNestFormList.html">FormItemNestFormList</a> — 数组子表单（C4，行增删 + min/max）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormActiveFilter.html">FormActiveFilter</a> — 生效筛选条件条（chips + × 移除 + 清除全部，纯 UI；投影逻辑在消费方 hook）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormInput.html">FormInput</a> — 输入框原语（el-input 全透传 + password 自动填充治理；影分身版 FormInputShadowClone 表头漏斗）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormSelect.html">FormSelect</a> — 选择器（options/remoteMethod/getOptions；影分身版 FormSelectShadowClone 表头漏斗）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormSortSwitchGroup.html">FormSortSwitchGroup / FormSortSwitch</a> — 复合排序组 + 单字段排序切换器（group 有 key 视角 / switch 无 key；<code>mode</code> cycle 首击升序对齐主流 / dual-arrow 双三角；<code>textType</code> label/状态文字；<code>shadowClone</code> 影分身 per-option teleportTo；依赖 display 族 ShadowClone）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormUpload.html">FormUpload</a> — 上传原语（ElUpload 封装，先传拿 URL 表单只提交 URL；<code>uploadFn</code> 注入不焊后端；上传中经 FORM_ITEM_CHANGE_LOADING 拦提交；进度 ElUpload 内置）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormUploadImage.html">FormUploadImage</a> — 图片上传（薄封装：accept image/* + 方形缩略图卡片 + 点击直达放大 + 悬停删除）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormUploadVideo.html">FormUploadVideo</a> — 视频上传（薄封装：accept video/* + 封面/占位 + 播放图标 + VideoPreviewTrigger 播放决策链）</li><li><a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormUploadAudio.html">FormUploadAudio</a> — 音频上传（薄封装：accept audio/* + 内联 <code>&lt;audio controls&gt;</code> 播放条即时试听；<strong>不建弹窗</strong>——业界音频无 lightbox 形态）</li><li>FormRadioGroup / FormTree / FormVerifyImage / FormVerifyCode — 文档待补</li></ul><h2 id="表单项内容的宽度约定-族级硬约定" tabindex="-1">表单项内容的宽度约定（族级硬约定） <a class="header-anchor" href="#表单项内容的宽度约定-族级硬约定" aria-label="Permalink to &quot;表单项内容的宽度约定（族级硬约定）&quot;">​</a></h2><p>EP 的 <code>.el-form-item__content</code> 是 <strong>flex 容器</strong>（<code>display:flex; flex-wrap:wrap; flex:1; align-items:center; min-width:0</code>）。 ⇒ <strong>凡要当表单项内容渲染的组件，其根盒 [MUST] 显式声明宽度行为</strong>， [MUST NOT] 依赖「块级元素会自己撑满」——<strong>那条规则在 flex 容器里不成立</strong>， 根盒会按 <code>flex:0 1 auto</code> 收缩到内容宽。</p><ul><li>想占整行 → 根盒 <code>width:100%</code> + <strong><code>min-width:0</code></strong>（flex item 的 <code>min-width</code> 默认 <code>auto</code>，长文本 / 宽表格会把它顶出容器，两条 [MUST] 成对给）</li><li>想按内容宽（chip / 按钮组 / 单选组）→ 显式 <code>display:inline-flex</code> 之类，<strong>也算声明</strong></li><li>本族现状：<code>FormItemNestForm</code> / <code>FormItemNestFormList</code> / <code>FormUpload</code> / <code>FormGroupTitle</code> / <code>FormTree</code> 走 <code>width:100%</code>； <code>FormRadioGroup</code>（EP <code>inline-flex</code>）、<code>FormSortSwitch(Group)</code> 按内容宽；<code>FormInput</code> / <code>FormSelect</code> / <code>FormDivider</code> 由 EP 自带 <code>width:100%</code></li><li>⚠️ <strong>内容宽的地方坏了也看不出来</strong>：一行里只要有个 <code>el-input</code>，收缩的根盒照样撑满—— 自查 / 守卫 [MUST] 用<strong>窄内容</strong>样例（如 148px 方卡）</li></ul><h2 id="跨族依赖" tabindex="-1">跨族依赖 <a class="header-anchor" href="#跨族依赖" aria-label="Permalink to &quot;跨族依赖&quot;">​</a></h2><ul><li>form 族 → display 族（单向）：<code>FormSort</code> 依赖 <code>ShadowClone</code>（分身机制）、<code>FormActiveFilter</code> 依赖 <code>ActionBtn</code>（清除全部按钮）</li><li>form 族 → modal 族（单向）：<code>FormUploadImage</code> 依赖 <code>ImagePreviewTrigger</code>（点击直达放大）、<code>FormUploadVideo</code> 依赖 <code>VideoPreviewTrigger</code>（播放弹窗决策链）</li></ul><h2 id="关键类型与-helper" tabindex="-1">关键类型与 helper <a class="header-anchor" href="#关键类型与-helper" aria-label="Permalink to &quot;关键类型与 helper&quot;">​</a></h2><ul><li>类型：<code>FormItemConfig</code> / <code>FormItemConfigList</code> / <code>FormMainInstance</code> / <code>FormSearchInstance</code> / <code>FormScope</code> / <code>FormAiSchema</code>（全部经 <code>./types</code> 导出）</li><li>helper：<code>nestFormItem</code>（C1）/ <code>nestFormItemList</code>（C4）/ <code>useNestForm</code> / <code>useNestFormList</code> / <code>useNestLayoutScale</code></li><li>工具：<code>generateFormData</code> / <code>parseFormData</code> / <code>stringifyFormData</code> / <code>patchFormData</code> / <code>swiftFormItemConfig</code> / <code>checkFormItemIsIgnore</code></li><li>分组 / 分割线 / 折叠（伪 item）：<code>swiftFormItemGroup</code> / <code>swiftFormItemDivider</code>——数据层被忽略、视觉照常渲染，折叠复用 <code>hide</code> 语义，见 <a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormMain.html">FormMain 文档「分组 / 分割线 / 折叠」</a></li><li>AI 填充数据层：<code>FormItemConfig</code> 可选 <code>type</code> / <code>description</code> / <code>aiIgnore</code> + <code>FormMainInstance</code> 的 <code>getAiSchema()</code>（OpenAI strict 裁剪 JSON Schema，<code>ai-schema.ts</code> 投影）/ <code>setValues()</code>（按 key 就地 patch），见 <a href="/done-coding-showcase/docs/core/src/components/form/docs/README-FormMain.html">FormMain 文档「AI 填充（数据层）」</a></li><li>内部不导出：<code>FormItem</code>（仅 FormMain 内部）、<code>use-form-submit</code>、<code>use-layout-by-container</code></li></ul><h2 id="范式页-apps-reference" tabindex="-1">范式页（apps/reference） <a class="header-anchor" href="#范式页-apps-reference" aria-label="Permalink to &quot;范式页（apps/reference）&quot;">​</a></h2><ul><li><code>/form/guide</code>（FormMain 最佳实践）/ <code>/form/container-breakpoint</code>（容器断点）/ <code>/form/submit-btn/showcase</code>、<code>/form/submit-panel/showcase</code>、<code>/form/nest-form/showcase</code>、<code>/form/nest-form-list/showcase</code>、<code>/form/nest-form-submit-panel/showcase</code></li></ul>',13)])])}const f=e(t,[["render",a]]);export{p as __pageData,f as default};
